/**
 * Zod contracts for file-based imports (#2494): the operator's source list
 * (`SWARM_IMPORT_SOURCES` / `SWARM_IMPORT_SOURCES_FILE`) and the optional
 * package manifest (`swarm-import.{yaml,yml,json}` at a package root).
 *
 * JSON Schema for both is generated by `bun run build:import-schema` into
 * `templates/import/`.
 */

import { isAbsolute } from "node:path";
import { z } from "zod";
import { isSafeBundlePath } from "../../extensions/bundle-path";

const SlugSchema = z
  .string()
  .min(1)
  .max(64)
  .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, "must be a lowercase slug");

/** Source-local identifier of one package item. Never a database id. */
const LocalIdSchema = z
  .string()
  .min(1)
  .max(200)
  .regex(
    /^[A-Za-z0-9][A-Za-z0-9._-]*$/,
    "must start with a letter or digit and use [A-Za-z0-9._-]",
  );

const PackagePathSchema = z
  .string()
  .min(1)
  .refine(
    isSafeBundlePath,
    "must be a relative POSIX path without empty, dot, or parent segments, at most 256 characters",
  );

export const ImportSourceSchema = z
  .object({
    id: SlugSchema.describe("Stable source id. Owns every resource this source imports."),
    type: z.literal("dir").describe("v1 ships the `dir` source only."),
    path: z
      .string()
      .min(1)
      .refine(isAbsolute, "must be an absolute path")
      .describe("Absolute path of the package root. Read only; mount it read-only."),
    onConflict: z
      .enum(["noop", "overwrite"])
      .default("noop")
      .describe(
        "`noop` keeps UI/API edits and skips resources this source does not own. `overwrite` makes the files win and adopts same-named resources.",
      ),
  })
  .strict();
export type ImportSource = z.infer<typeof ImportSourceSchema>;

export const ImportSourcesSchema = z.array(ImportSourceSchema).superRefine((sources, ctx) => {
  const seen = new Set<string>();
  sources.forEach((source, index) => {
    if (seen.has(source.id)) {
      ctx.addIssue({ code: "custom", path: [index, "id"], message: "duplicate source id" });
    }
    seen.add(source.id);
  });
});

const ManifestAgentSchema = z
  .object({
    name: z.string().min(1).max(200).optional().describe("Agent name. Use `id` when names repeat."),
    id: z.string().min(1).max(200).optional().describe("Agent id, as the agent registers."),
    instructions: PackagePathSchema.optional().describe(
      "Markdown role instructions. Written to the agent's IDENTITY.md profile field.",
    ),
    skills: z
      .array(LocalIdSchema)
      .optional()
      .describe("Ids of skills declared in this manifest to install on the agent."),
  })
  .strict()
  .refine((agent) => (agent.name === undefined) !== (agent.id === undefined), {
    message: "set exactly one of name or id",
  });
export type ManifestAgent = z.infer<typeof ManifestAgentSchema>;

export const ImportManifestSchema = z
  .object({
    $schema: z.string().optional(),
    version: z.literal(1).optional().describe("Manifest format version."),
    workflows: z
      .array(
        z
          .object({
            id: LocalIdSchema,
            file: PackagePathSchema.describe("YAML or JSON workflow file."),
          })
          .strict(),
      )
      .optional(),
    skills: z
      .array(
        z
          .object({
            id: LocalIdSchema,
            dir: PackagePathSchema.describe("Directory holding SKILL.md and optional files/**."),
          })
          .strict(),
      )
      .optional(),
    scripts: z
      .array(
        z
          .object({
            name: z.string().min(1).max(200).describe("Global script name."),
            file: PackagePathSchema.describe("Script source file."),
            description: z.string().min(1),
            intent: z.string().min(1).optional().describe("Defaults to `description`."),
          })
          .strict(),
      )
      .optional(),
    agents: z.array(ManifestAgentSchema).optional(),
  })
  .strict();
export type ImportManifest = z.infer<typeof ImportManifestSchema>;

/**
 * One line per issue: field path plus zod's message. Values never appear, and
 * unknown keys are reported without their names, so a secret pasted into the
 * wrong field is not echoed into the boot log.
 */
export function formatIssues(prefix: string, issues: readonly z.core.$ZodIssue[]): string[] {
  return issues.map((issue) => {
    const path = [prefix, ...issue.path.map(String)].filter(Boolean).join(".");
    const message = issue.code === "unrecognized_keys" ? "unknown field" : issue.message;
    return `${path}: ${message}`;
  });
}
